var bolt=new Servo(), entry='', keys=[{p:2,n:'A',st:1,t:-99},{p:3,n:'B',st:1,t:-99}];
function setup(){pinMode(2,INPUT_PULLUP);pinMode(3,INPUT_PULLUP);pinMode(4,OUTPUT);bolt.attach(9);bolt.write(0);}
function resync(){ keys.forEach(function(k){k.st=digitalRead(k.p);k.t=millis();}); }
function loop(){ var now=millis();
  keys.forEach(function(k){ var r=digitalRead(k.p); if(r!==k.st && now-k.t>25){ k.st=r; k.t=now; if(r===0) entry+=k.n; } });
  if(entry.length===4){ if(entry==='AABA'){bolt.write(90);delay(3000);bolt.write(0);} else {digitalWrite(4,1);delay(500);digitalWrite(4,0);} entry=''; resync(); }
  delay(2);}
